import React, { useState } from 'react';
import {
  Box,
  Typography,
  TextField,
  Button,
  Paper,
  Link,
  Alert,
  Stack,
} from '@mui/material';
import blogConfig from './blog-config.json';

const RSS_FEED_PATH = '/rss.xml';

function BlogSubscribe() {
  const [email, setEmail] = useState('');
  const [status, setStatus] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const hasNewsletter = Boolean(blogConfig.buttondownUsername?.trim());
  const rssFeedUrl = `${window.location.origin}${RSS_FEED_PATH}`;

  const handleNewsletterSubmit = async (event) => {
    event.preventDefault();
    const trimmedEmail = email.trim();

    if (!trimmedEmail) {
      setStatus({ type: 'error', message: 'Please enter your email address.' });
      return;
    }

    setSubmitting(true);
    setStatus(null);

    try {
      const response = await fetch(
        `https://buttondown.email/api/emails/embed-subscribe/${blogConfig.buttondownUsername}`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          body: new URLSearchParams({ email: trimmedEmail }),
        },
      );

      if (response.ok) {
        setEmail('');
        setStatus({
          type: 'success',
          message: 'You are subscribed. Check your inbox to confirm.',
        });
      } else {
        setStatus({
          type: 'error',
          message: 'Could not subscribe right now. Please try again later.',
        });
      }
    } catch (error) {
      setStatus({
        type: 'error',
        message: 'Could not subscribe right now. Please try again later.',
      });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Paper
      elevation={0}
      sx={{
        p: 3,
        mb: 4,
        border: '1px solid',
        borderColor: 'divider',
        backgroundColor: 'grey.50',
      }}
    >
      <Typography
        variant="h6"
        gutterBottom
        sx={{ fontFamily: "'Source Serif 4', serif" }}
      >
        Get notified when new posts go live.
      </Typography>

      <Stack spacing={2}>

        {hasNewsletter && (
          <Box component="form" onSubmit={handleNewsletterSubmit}>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
              <TextField
                type="email"
                size="small"
                placeholder="you@example.com"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                disabled={submitting}
                fullWidth
                inputProps={{ 'aria-label': 'Email address' }}
                sx={{
                  '& .MuiInputBase-input': {
                    fontFamily: "'Source Serif 4', serif",
                  },
                }}
              />
              <Button
                type="submit"
                variant="contained"
                disabled={submitting}
                sx={{
                  minWidth: { sm: 140 },
                  fontFamily: "'Source Serif 4', serif",
                  backgroundColor: '#1e40af',
                  '&:hover': { backgroundColor: '#1e3a8a' },
                }}
              >
                {submitting ? 'Subscribing…' : 'Subscribe'}
              </Button>
            </Stack>
          </Box>
        )}
        <Box>
          <Link
            href={RSS_FEED_PATH}
            sx={{
              color: '#1e40af',
              textDecoration: 'none',
              fontFamily: "'Source Serif 4', serif",
              '&:hover': { textDecoration: 'underline' },
            }}
          >
            Subscribe via RSS
          </Link>
        </Box>
      </Stack>

      {status && (
        <Alert severity={status.type} sx={{ mt: 2 }}>
          <Typography variant="body2" sx={{ fontFamily: "'Source Serif 4', serif" }}>
            {status.message}
          </Typography>
        </Alert>
      )}
    </Paper>
  );
}

export default BlogSubscribe;
